/**
 * Definition for a binary tree node.
 * class TreeNode {
 *      constructor(val = 0, left = null, right = null){
 *          this.data = val;
 *          this.left = null;
 *          this.right = null;
 *      }
 * }
 **/

class BSTIterator {
  constructor(root) {
    this.prev = null;
    let temp = root;
    let dummyNode = new TreeNode("#");
    dummyNode.right = this.buildBST(temp);
    this.iterator = dummyNode;
  }

  hasNext() {
    return this.iterator.right !== null;
  }

  next() {
    this.iterator = this.iterator.right;
    return this.iterator.data;
  }

  buildBST(root) {
    if (root === null) return;
    this.buildBST(root.right);
    root.right = this.prev;
    this.prev = root;
    this.buildBST(root.left);
    root.left = null;
    return this.prev;
  }
}

