/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int data;
 *     TreeNode *left;
 *     TreeNode *right;
 *      TreeNode(int val) : data(val) , left(nullptr) , right(nullptr) {}
 * };
 **/

class BSTIterator {
   public:
    stack<TreeNode*> st;
    BSTIterator(TreeNode* root) {
        while (root != nullptr) {
            st.push(root);
            root = root->left;
        }
    }

    bool hasNext() { 
        return st.size(); 
    }

    int next() {
            TreeNode* x = st.top();
            st.pop();

            int ans = x->data;

            x = x->right;

            while (x != nullptr) {
                st.push(x);
                x = x->left;
            }
            return ans;

    }
};

